 private CarrierBookingExecution execution(String account,UUID epoch){return new CarrierBookingExecution(jdbc,manager,audit,clock,ProviderHttp.Mode.MOCK,account,epoch,Instant.EPOCH,metrics);}
 private Map<String,Object> context(){var address=new CarrierValues.Address("Synthetic Recipient","+2348000000001","Synthetic Street",null,"Lagos","LA",null,"NG");var destination=(ObjectNode)EventCodec.JSON.valueToTree(address);destination.put("label","Synthetic saved").put("isDefault",false);return Map.of("shipmentId",shipment,"orderId",UUID.randomUUID(),"address",destination,"shipper",address,"serviceCode","SYNTHETIC_SERVICE","packages",java.util.stream.IntStream.range(0,physicalPieces).mapToObj(i->new CarrierValues.Parcel(UUID.randomUUID(),"1","1.2","10","10","10")).toList(),"bookingReference",reference,"mode","MOCK");}
 private JsonNode result(){var pieces=java.util.stream.IntStream.range(0,physicalPieces).mapToObj(i->Map.of("trackingNumber",Long.toString(123456789012L+i),"packageDocuments",List.of(Map.of("contentType","LABEL","docType","PDF","encodedLabel",encodedLabel)))).toList();return EventCodec.JSON.valueToTree(Map.of("transactionShipments",List.of(Map.of("masterTrackingNumber","123456789012","pieceResponses",pieces))));}

 private CarrierBookingExecution.Claim claim(){return execution.claim(shipment).orElseThrow();}
 private CarrierBookingExecution.Claim prepared(CarrierBookingExecution.Claim claim){var context=CarrierCreationContext.parse(EventCodec.JSON.valueToTree(context()),shipment,reference,provider.mode());return execution.prepare(claim,requests.build(context,LocalDate.now(clock)),clock.instant().plusSeconds(600)).orElseThrow();}
 private JsonNode checkpoint(){return EventCodec.JSON.readTree(jdbc.queryForObject("SELECT cursor::text FROM integration.integration_job WHERE id=?",String.class,job));}
 @Test void twelveWorkersClaimOnePairedLeaseAndFreshSubmissionCommitsBeforeProviderHttp()throws Exception{
  var results=new ArrayList<CarrierBookingExecution.Claim>();try(var pool=Executors.newFixedThreadPool(12)){var start=new CountDownLatch(1);var tasks=new ArrayList<Future<Optional<CarrierBookingExecution.Claim>>>();for(int i=0;i<12;i++)tasks.add(pool.submit(()->{start.await();return execution.claim(shipment);}));start.countDown();for(var task:tasks)task.get(15,TimeUnit.SECONDS).ifPresent(results::add);}assertThat(results).hasSize(1);var claim=results.getFirst();assertThat(claim.mayCreate()).isTrue();assertThat(claim.correlation()).isEqualTo(correlation);assertThat(Duration.between(clock.instant(),claim.lease())).isEqualTo(Duration.ofSeconds(120));var submitted=execution.submit(claim,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));assertThat(submitted.persisted()).isTrue();assertThat(submitted.toString()).doesNotContain("transactionShipments");assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);assertThat(checkpoint().path("stage").asString()).isEqualTo("LABEL_PENDING");assertThat(jdbc.queryForObject("SELECT state FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo("CLAIMED");assertThat(jdbc.queryForObject("SELECT label_object_key FROM integration.carrier_booking WHERE id=?",String.class,booking)).isNull();assertThat(execution.claim(shipment)).isEmpty();
 }
 @Test void expiredPreparationAndStaleWorkerCannotRebookOrOverwriteNewGeneration(){var prepared=prepared(claim());String hash=prepared.requestHash();clock.advance(121);assertThat(execution.acceptedAsync(prepared,"stale-job")).isFalse();var recovered=claim();assertThat(recovered.mayCreate()).isFalse();assertThat(recovered.requestHash()).isEqualTo(hash);assertThat(execution.unknown(prepared,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isFalse();assertThatThrownBy(()->execution.submit(recovered,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isZero();assertThat(reads.get()).isZero();assertThat(execution.unknown(recovered,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isTrue();assertThat(jdbc.queryForObject("SELECT state FROM integration.integration_job WHERE id=?",String.class,job)).isEqualTo("UNKNOWN");}
 @Test void changedRestoreGenerationAndLegacyCheckpointNeverGainCreatePermission(){var changed=execution(provider.accountFingerprint(),UUID.randomUUID());var restored=changed.claim(shipment).orElseThrow();assertThat(restored.compatible()).isTrue();assertThat(restored.mayCreate()).isFalse();assertThat(changed.unknown(restored,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isTrue();clock.advance(31);jdbc.update("UPDATE integration.integration_job SET cursor='{}'::jsonb WHERE id=?",job);var legacy=claim();assertThat(legacy.mayCreate()).isFalse();assertThat(legacy.compatible()).isFalse();assertThatThrownBy(()->prepared(legacy)).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isZero();}
