 @Test void preparationAndAcceptanceRollbackBothRowsWhenAuditFails(){var claim=claim();String hash=claim.requestHash();admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->prepared(claim)).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(checkpoint().path("stage").asString()).isEqualTo("INTENT");assertThat(jdbc.queryForObject("SELECT request_hash FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo(hash);var prepared=prepared(claim);admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->execution.acceptedAsync(prepared,"synthetic-async-1")).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(checkpoint().path("stage").asString()).isEqualTo("PREPARED");assertThat(jdbc.queryForObject("SELECT provider_shipment_id FROM integration.carrier_booking WHERE id=?",String.class,booking)).isNull();assertThat(execution.acceptedAsync(prepared,"synthetic-async-1")).isTrue();}
 @Test void acceptedAsyncJobRetrievesReadOnlyAfterPendingResultWithoutCreationContext(){scenario="async";ready=false;var submitted=execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));assertThat(submitted.persisted()).isTrue();assertThat(checkpoint().path("stage").asString()).isEqualTo("ASYNC");contextAllowed=false;clock.advance(31);var pending=claim();assertThat(pending.mayCreate()).isFalse();assertThatThrownBy(()->execution.retrieve(pending,provider)).isInstanceOf(Problem.Failure.class);assertThat(checkpoint().path("asyncJobId").asString()).isEqualTo("synthetic-async-1");ready=true;clock.advance(31);assertThat(execution.retrieve(claim(),provider).persisted()).isTrue();assertThat(checkpoint().path("stage").asString()).isEqualTo("LABEL_PENDING");assertThat(writes.get()).isEqualTo(1);assertThat(polls.get()).isEqualTo(2);assertThat(reads.get()).isEqualTo(1);}
