 @Test void expiredQualificationAndWrongBusinessReferenceCannotPrepare(){var claimed=claim();var context=CarrierCreationContext.parse(EventCodec.JSON.valueToTree(context()),shipment,reference,provider.mode());var request=requests.build(context,LocalDate.now(clock));assertThatThrownBy(()->execution.prepare(claimed,request,clock.instant())).isInstanceOf(Problem.Failure.class);((ObjectNode)request.path("requestedShipment").path("requestedPackageLineItems").path(0).path("customerReferences").path(0)).put("value",UUID.randomUUID().toString());assertThatThrownBy(()->execution.prepare(claimed,request,clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(checkpoint().path("stage").asString()).isEqualTo("INTENT");assertThat(writes.get()).isZero();}
