 private CarrierBookingWorker worker()throws Exception{String path=System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE");Assumptions.assumeTrue(path!=null,"isolated TLS/SigV4 label fixture required");storageConfig=EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(path)));var env=new org.springframework.mock.env.MockEnvironment().withProperty("APP_ENV","test").withProperty("NIGSON_SECURITY_ENABLED","true").withProperty("NIGSON_AWS_REGION",storageConfig.path("region").asString()).withProperty("NIGSON_S3_LOCAL_ENDPOINT",storageConfig.path("endpoint").asString()).withProperty("NIGSON_S3_LOCAL_CA",storageConfig.path("ca").asString()).withProperty("NIGSON_S3_PRIVATE_BUCKET",storageConfig.path("buckets").path(2).asString());var factory=new CarrierLabelConfiguration();labelClient=factory.carrierLabelClient(env);var labels=factory.carrierLabelStorage(labelClient,env);return new CarrierBookingWorker(execution,source,requests,provider,labels,clock,clock.instant().plusSeconds(600));}
