 private com.nigson.shared.security.PrivateWorkload.Proof staffReconciliationProof(){var route=com.nigson.shared.security.PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-196")).findFirst().orElseThrow();var actor=new com.nigson.shared.security.ActorAssertion.Actor(UUID.randomUUID(),"https://identity.synthetic.invalid/realms/test","synthetic-operations",null,Set.of("OPERATIONS"),Set.of(route.scope()),clock.instant());return new com.nigson.shared.security.PrivateWorkload.Proof(route.client(),"synthetic-carrier-staff",route,actor);}
