 @Test void staffReconciliationNeverGrantsFreshCreationPermission(){String original=checkpoint().toString(),hash=jdbc.queryForObject("SELECT request_hash FROM integration.carrier_booking WHERE id=?",String.class,booking);UUID command=UUID.randomUUID();var proof=staffReconciliationProof();var first=reconciliation().reconcile(proof,shipment,reconciliationInput(),command,correlation);assertThat(first.jobId()).isEqualTo(job);assertThat(first.shipmentId()).isEqualTo(shipment);assertThat(first.state()).isEqualTo("UNKNOWN");assertThat(checkpoint().toString()).isEqualTo(original);assertThat(jdbc.queryForObject("SELECT request_hash FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo(hash);assertThat(jdbc.queryForObject("SELECT attempt_count FROM integration.integration_job WHERE id=?",Integer.class,job)).isZero();long version=jdbc.queryForObject("SELECT version FROM integration.integration_job WHERE id=?",Long.class,job);assertThat(reconciliation().reconcile(proof,shipment,reconciliationInput(),command,correlation)).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT version FROM integration.integration_job WHERE id=?",Long.class,job)).isEqualTo(version);assertThat(claim().mayCreate()).isFalse();assertThat(writes.get()).isZero();assertThat(reads.get()).isZero();}
