 @Test void staffReconciliationRequiresExactScopeRoleAndRecentMfa(){var p=staffReconciliationProof();var actor=p.actor();var stale=new com.nigson.shared.security.ActorAssertion.Actor(actor.party(),actor.identityIssuer(),actor.identitySubject(),null,actor.roles(),actor.scopes(),clock.instant().minusSeconds(901));for(var denied:List.of(new com.nigson.shared.security.PrivateWorkload.Proof("nigson-experience",p.subject(),p.route(),actor),new com.nigson.shared.security.PrivateWorkload.Proof(p.client(),p.subject(),p.route(),null),new com.nigson.shared.security.PrivateWorkload.Proof(p.client(),p.subject(),p.route(),stale)))assertThatThrownBy(()->reconciliation().reconcile(denied,shipment,reconciliationInput(),UUID.randomUUID(),correlation)).hasMessage("ACTOR_TRUST_REJECTED");assertThat(checkpoint().path("stage").asString()).isEqualTo("INTENT");}
